def apply(inputs, premises):
    question = inputs["current_question"]
    class_match = False
    for recipient_class in premises["permitted_representative_classes"]:
        if recipient_class in question:
            class_match = True
    if "professional advisors" in question:
        if "legal advisors" in premises["permitted_representative_classes"] or "financial advisors" in premises["permitted_representative_classes"] or "accountants" in premises["permitted_representative_classes"]:
            class_match = True
    exception_applies = class_match and premises["representatives_must_be_confidentiality_bound"] and premises["representatives_must_have_need_to_know"] and premises["disclosure_limited_to_stated_purpose"]
    return {"exception_applies": exception_applies}

def apply(inputs, premises):
    question = inputs["current_question"]
    is_disclosure_permission_query = "Receiving Party" in question and "may share some Confidential Information" in question
    if not is_disclosure_permission_query:
        answer = "NotMentioned"
    elif not premises["general_third_party_nondisclosure_rule"]:
        answer = "NotMentioned"
    elif inputs["representative_exception_applies"]:
        answer = "Entailment"
    elif "third-parties" in question:
        answer = "Contradiction"
    elif premises["recipient_exception_expressly_modifies_general_rule"]:
        answer = "Contradiction"
    else:
        answer = "NotMentioned"
    return {"answer": answer}
